use std::collections::HashMap;
use std::sync::{Arc, RwLock};

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum Role {
    Admin,
    Writer,
    Reader,
    Guest,
}

impl Role {
    fn privilege_level(&self) -> u8 {
        match self {
            Role::Admin => 255,
            Role::Writer => 128,
            Role::Reader => 64,
            Role::Guest => 0,
        }
    }
}

#[derive(Debug, Clone)]
pub struct CacheEntry {
    pub value: Vec<u8>,
    pub min_role: Role,
    pub owner_id: u64,
    pub namespace: String,
}

#[derive(Debug, Clone)]
pub struct Session {
    pub user_id: u64,
    pub role: Role,
    pub namespace_grants: Vec<String>,
}

pub struct DistributedCacheClient {
    store: Arc<RwLock<HashMap<String, CacheEntry>>>,
    sessions: Arc<RwLock<HashMap<String, Session>>>,
    namespace_hierarchy: Arc<RwLock<HashMap<String, Vec<String>>>>,
}

impl DistributedCacheClient {
    pub fn new() -> Self {
        Self {
            store: Arc::new(RwLock::new(HashMap::new())),
            sessions: Arc::new(RwLock::new(HashMap::new())),
            namespace_hierarchy: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    pub fn register_session(&self, token: &str, session: Session) {
        let mut sessions = self.sessions.write().unwrap();
        sessions.insert(token.to_string(), session);
    }

    pub fn set_namespace_hierarchy(&self, parent: &str, children: Vec<String>) {
        let mut hierarchy = self.namespace_hierarchy.write().unwrap();
        hierarchy.insert(parent.to_string(), children);
    }

    fn resolve_effective_namespaces(&self, session: &Session) -> Vec<String> {
        let hierarchy = self.namespace_hierarchy.read().unwrap();
        let mut effective = session.namespace_grants.clone();
        for grant in &session.namespace_grants {
            if let Some(children) = hierarchy.get(grant) {
                effective.extend(children.iter().cloned());
            }
        }
        effective
    }

    fn check_access(&self, session: &Session, entry: &CacheEntry, operation: &str) -> bool {
        // Step 1: Check role-based privilege level
        let required_level = entry.min_role.privilege_level();
        let session_level = session.role.privilege_level();

        if session_level < required_level {
            return false;
        }

        // Step 2: Check namespace access
        let effective_namespaces = self.resolve_effective_namespaces(session);
        let has_namespace_access = effective_namespaces.contains(&entry.namespace);

        // Step 3: Owner bypass - owners can always access their own entries
        let is_owner = session.user_id == entry.owner_id;

        // Step 4: For write operations, require Writer+ role OR ownership
        if operation == "write" || operation == "delete" {
            if is_owner {
                return true;
            }
            if session_level < Role::Writer.privilege_level() {
                return false;
            }
        }

        // Final: must have namespace access OR be owner
        has_namespace_access || is_owner
    }

    pub fn get(&self, token: &str, key: &str) -> Result<Vec<u8>, String> {
        let sessions = self.sessions.read().unwrap();
        let session = sessions.get(token).ok_or("Invalid session")?.clone();
        drop(sessions);

        let store = self.store.read().unwrap();
        let entry = store.get(key).ok_or("Key not found")?.clone();
        drop(store);

        if self.check_access(&session, &entry, "read") {
            Ok(entry.value)
        } else {
            Err("Access denied".to_string())
        }
    }

    pub fn put(&self, token: &str, key: &str, value: Vec<u8>, namespace: &str, min_role: Role) -> Result<(), String> {
        let sessions = self.sessions.read().unwrap();
        let session = sessions.get(token).ok_or("Invalid session")?.clone();
        drop(sessions);

        // Check if key already exists - need write access to overwrite
        let store = self.store.read().unwrap();
        if let Some(existing) = store.get(key) {
            let existing_clone = existing.clone();
            drop(store);
            if !self.check_access(&session, &existing_clone, "write") {
                return Err("Access denied: cannot overwrite".to_string());
            }
        } else {
            drop(store);
        }

        // Verify the user has access to the target namespace
        let effective_namespaces = self.resolve_effective_namespaces(&session);
        if !effective_namespaces.contains(&namespace.to_string()) {
            return Err("Access denied: namespace not granted".to_string());
        }

        let entry = CacheEntry {
            value,
            min_role,
            owner_id: session.user_id,
            namespace: namespace.to_string(),
        };

        let mut store = self.store.write().unwrap();
        store.insert(key.to_string(), entry);
        Ok(())
    }

    pub fn delete(&self, token: &str, key: &str) -> Result<(), String> {
        let sessions = self.sessions.read().unwrap();
        let session = sessions.get(token).ok_or("Invalid session")?.clone();
        drop(sessions);

        let store = self.store.read().unwrap();
        let entry = store.get(key).ok_or("Key not found")?.clone();
        drop(store);

        if self.check_access(&session, &entry, "delete") {
            let mut store = self.store.write().unwrap();
            store.remove(key);
            Ok(())
        } else {
            Err("Access denied".to_string())
        }
    }

    /// Batch operation: atomically move entries between namespaces
    /// Requires write access to source entries and namespace access to target
    pub fn batch_move(&self, token: &str, keys: &[&str], target_namespace: &str) -> Result<u64, String> {
        let sessions = self.sessions.read().unwrap();
        let session = sessions.get(token).ok_or("Invalid session")?.clone();
        drop(sessions);

        let effective_namespaces = self.resolve_effective_namespaces(&session);
        if !effective_namespaces.contains(&target_namespace.to_string()) {
            return Err("Access denied: target namespace not granted".to_string());
        }

        let mut moved: u64 = 0;
        let mut store = self.store.write().unwrap();

        for key in keys {
            if let Some(entry) = store.get_mut(*key) {
                // Check write access using privilege comparison
                let required = entry.min_role.privilege_level();
                let has_level = session.role.privilege_level() >= required;
                let is_owner = session.user_id == entry.owner_id;

                // BUG: Uses bitwise OR instead of logical OR for the final check.
                // When has_level is true (non-zero u8 comparison result stored as bool = 1)
                // and is_owner is false (0), the bitwise OR works correctly.
                // BUT: the namespace check is skipped entirely here - we only checked
                // target namespace, not source namespace access.
                // A Reader (privilege 64) can move Admin-owned entries (min_role=Reader)
                // from namespaces they DON'T have access to, as long as they have
                // target namespace access. The check_access function properly validates
                // source namespace, but batch_move reimplements the check incorrectly.
                if has_level | is_owner {
                    entry.namespace = target_namespace.to_string();
                    moved += 1;
                }
            }
        }

        Ok(moved)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_access_control() {
        let client = DistributedCacheClient::new();
        client.register_session("admin_tok", Session {
            user_id: 1,
            role: Role::Admin,
            namespace_grants: vec!["system".to_string()],
        });
        client.register_session("reader_tok", Session {
            user_id: 2,
            role: Role::Reader,
            namespace_grants: vec!["public".to_string()],
        });

        client.put("admin_tok", "secret", b"classified".to_vec(), "system", Role::Admin).unwrap();
        assert!(client.get("reader_tok", "secret").is_err());
    }
}
